Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
    MonarchSkeleton(
        modifier = Modifier.size(({{shapes.0.width}} * 16).dp, ({{shapes.0.height}} * 16).dp),
        shape = MonarchSkeletonShape.{{shapes.0.shape|pascal}},
    )
    MonarchSkeleton(
        modifier = Modifier.width(({{shapes.1.width}} * 16).dp),
        shape = MonarchSkeletonShape.{{shapes.1.shape|pascal}},
    )
    MonarchSkeleton(
        modifier = Modifier.size(({{shapes.2.width}} * 16).dp, ({{shapes.2.height}} * 16).dp),
        shape = MonarchSkeletonShape.{{shapes.2.shape|pascal}},
    )
}

